entries[18984] = { ["name"] = "Dimensionszerfetzer: Ewige Warte", ["text"] = "Wird bei Benutzung gebundenSchmuck\nBenötigt Ingenieurskunst (260)\nBenötigt Gobliningenieur\nBenutzen: Reißt die dimensionalen Mauern ein, um Euch zur Ewigen Warte in Winterquell zu transportieren. Es gibt da zwar einige technische Probleme, die manchmal auftreten, aber das muss man halt bei dem Ingenieurswesen der Goblins mit einkalkulieren! (4 Std. Abklingzeit)\nVerkaufspreis:" }
entries[18986] = { ["name"] = "Extrem sicherer Transporter: Gadgetzan", ["text"] = "Wird bei Benutzung gebundenSchmuck\nBenötigt Ingenieurskunst (260)\nBenötigt Gnomeningenieur\nBenutzen: Transportiert Euch sicher nach Gadgetzan in Tanaris! Die Betonung liegt auf Sicher! Jup, nichts könnte Euch jemals passieren wenn Ihr diese Apparatur benutzt! (4 Std. Abklingzeit)\nVerkaufspreis:" }
