entries[19957] = { ["name"] = "Hazza'rahs Amulett der Zerstörung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nKlassen: Hexenmeister\nBenötigt Stufe 60\nBenutzen: Erhöht Eure kritische Zaubertrefferwertung 20 Sek. lang um 140. (3 Min Abklingzeit)\n\nRoben des Besessenen (0/5)\nKezans unaufhaltsame Schmach\nHazza'rahs Amulett der Zerstörung\nHandlappen des Zandalaribesessenen\nMantel des Zandalaribesessenen\nRobe des besessenen Zandalari\n(2) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht den Schaden Eures Zaubers 'Verderbnis' um 2%.\n(5) Set : Verringert die Abklingzeit Eures Zaubers 'Todesmantel' um 15%." }
