entries[20012] = { ["name"] = "Rezept: Großer Trank des traumlosen Schlafs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (275)\nBenötigt Stamm der Zandalar\n- Freundlich\nBenutzen: Lehrt Euch die Herstellung eines großen Tranks des traumlosen Schlafs.\nVerkaufspreis:\nGroßer Trank des traumlosen Schlafs\nBenötigt Stufe 55\nBenutzen: Versetzt den Anwender 12 Sek. lang in einen traumlosen Schlaf. In dieser Zeit heilt der Anwender 2100 Punkte Gesundheit und 2100 Punkte Mana. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Traumblatt (2), Goldener Sansam , Kristallphiole" }
entries[20013] = { ["name"] = "Rezept: Trank der lebhaften Aktion", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (285)\nBenötigt Stamm der Zandalar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Tranks der lebhaften Aktion.\nVerkaufspreis:\nTrank der lebhaften Aktion\nBenötigt Stufe 47\nBenutzen: Macht Euch 5 Sek. lang immun gegen betäubungs- und bewegungseinschränkende Effekte und entfernt alle bestehenden Effekte dieser Art von Euch. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Eiskappe (2), Bergsilbersalbei (2), Herz der Wildnis (2), Kristallphiole" }
entries[20014] = { ["name"] = "Rezept: Erheblicher Trollbluttrank", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchimie (290)\nBenötigt Stamm der Zandalar\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung eines erheblichen Trollbluttranks.\nVerkaufspreis:\nErheblicher Trollbluttrank\nBenötigt Stufe 53\nBenutzen: 1 Stunde lang alle 5 Sekunden 20 Gesundheit regenerieren. Wächterelixier. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Gromsblut , Pestblüte (2), Kristallphiole" }
