entries[20033] = { ["name"] = "Robe des besessenen Zandalari", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBrust Stoff\n114 Rüstung\n+35 Ausdauer\nHaltbarkeit 100 / 100\nKlassen: Hexenmeister\nAnlegen: Erhöht Eure Zaubertrefferwertung um 8.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 27.\n\nRoben des Besessenen (0/5)\nKezans unaufhaltsame Schmach\nHazza'rahs Amulett der Zerstörung\nHandlappen des Zandalaribesessenen\nMantel des Zandalaribesessenen\nRobe des besessenen Zandalari\n(2) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 12.\n(3) Set : Erhöht den Schaden Eures Zaubers 'Verderbnis' um 2%.\n(5) Set : Verringert die Abklingzeit Eures Zaubers 'Todesmantel' um 15%." }
entries[20034] = { ["name"] = "Robe des der Zandalari-Illusionisten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBrust Stoff\n114 Rüstung\n+23 Ausdauer\n+24 Intelligenz\nHaltbarkeit 100 / 100\nKlassen: Magier\nAnlegen: Erhöht Eure Zaubertrefferwertung um 8.\nAnlegen: Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 27.\n\nRoben des Illusionisten (0/5)\nJuwel von Kajaro\nHazza'rahs Amulett der Magie\nHandlappen des Zandalari-Illusionisten\nMantel des Zandalari-Illusionisten\nRobe des der Zandalari-Illusionisten\n(2) Set : Erhöht durch Zauber und magische Effekte verursachten Schaden und Heilung um bis zu 12.\n(3) Set : Verringert die Manakosten Eurer Zauber 'Arkane Intelligenz' und 'Arkane Brillanz' um 5%.\n(5) Set : Reduziert die Zauberzeit Eures Zaubers 'Flammenstoß' um 0.5 Sek." }
entries[20035] = { ["name"] = "Gletscherstachel", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n31 - 59 Schaden Tempo 1.30\n(34.62 Schaden pro Sekunde)\n+4 Intelligenz\nHaltbarkeit 65 / 65\nAnlegen: Eure Frostblitzzauber haben eine Chance von 6%, dass sie 50 Mana regenerieren.\n\"Teuflische Runen zieren die Klinge.\"\nVerkaufspreis:" }
